<?php
 namespace Pterodactyl\Notifications; use Pterodactyl\Models\User; use Illuminate\Bus\Queueable; use Pterodactyl\Services\Dezerx\Emails; use Illuminate\Notifications\Notification; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; class AccountRegistered extends Notification implements ShouldQueue { use Queueable; public function __construct(public User $user) { } public function via(): array { return ['mail']; } public function toMail(): MailMessage { return Emails::apply(new MailMessage(), 'account-registered', [ 'name' => $this->user->name, 'username' => $this->user->username, 'email' => $this->user->email, ]); } } 